/** Source declarations consumed by source-assessment.ts; runtime availability is evaluated there. */
export type ManagementFormula =
  | { readonly operator: 'RATIO_PERCENT'; readonly numerator: string; readonly denominator: string; readonly input: 'INTEGER' | 'DECIMAL_MONEY' | 'DECIMAL_SCORE'; readonly fixedDenominator?: number; readonly numeratorSubset: boolean }
  | { readonly operator: 'COUNT'; readonly numerator: string }
  | { readonly operator: 'DOCUMENT_PRESENCE'; readonly numerator: string; readonly presentValue: 1; readonly presentScore: 100 }
  | { readonly operator: 'COMPONENTS_ONLY'; readonly components: readonly { readonly key: string; readonly numerator: string; readonly denominator: string; readonly input: 'INTEGER' | 'DECIMAL_MONEY' }[] }
  | { readonly operator: 'UNRESOLVED_MONTH_MULTIPLIER'; readonly numerator: string; readonly denominator: string; readonly multiplier: 12; readonly candidates: readonly ['N_DIV_D_TIMES_12_TIMES_100', 'N_DIV_D_TIMES_12_DENOMINATOR_TIMES_100'] };

export type ManagementDecision = {
  readonly definitionId: `DO26-K1-R${number}`;
  readonly sourceRef: string;
  readonly kind: 'DOCUMENT' | 'RATIO' | 'CHECKLIST' | 'SNAPSHOT' | 'COUNT' | 'COMPOSITE' | 'FREQUENCY' | 'TIME_AVAILABILITY' | 'SCORE_RATIO' | 'FINANCIAL_RATIO';
  readonly readiness: 'CONTEXT_REQUIRED' | 'MEASUREMENT_ONLY' | 'SOURCE_CONFLICT';
  readonly formula: ManagementFormula;
  readonly target: {
    readonly raw: string | number;
    readonly excelNumberFormat: 'General' | '0%';
    readonly value: number | null;
    readonly unit: 'PERCENT' | 'COUNT' | 'DOCUMENT';
    readonly comparator: 'MIN' | 'UNRESOLVED';
    readonly basis: 'LITERAL_MINIMUM' | 'TECHNICAL_MINIMUM' | 'UNRESOLVED';
  };
  readonly period: 'ANNUAL' | 'AS_OF' | 'MONTH' | 'QUARTER' | 'PREVIOUS_YEAR_DOCUMENT' | 'NEXT_YEAR_DOCUMENT' | 'TWO_YEAR_DOCUMENT_WINDOW';
  readonly criteria: readonly string[];
  readonly requiredContext: readonly string[];
  readonly thresholds?: Readonly<Record<string, number | readonly number[]>>;
  readonly applicability?: 'EXCLUDE_UNPREPARED_Q1_ONLY' | 'EXCLUDE_IF_NO_PANTI_SEHAT' | 'EXCLUDE_IF_NO_PONPES' | 'EXCLUDE_IF_NO_SCHOOL_INCLUDE_SCHOOLS_WITHOUT_SBH' | 'EXCLUDE_ABSENT_POSKESTREN_SBH_COMPONENTS_ONLY';
  readonly unresolved: readonly string[];
};

